import csv
import io
import re
from collections import Counter
from typing import Any


def parse_csv(raw_csv: str) -> dict[str, Any]:
    expected_width = 18
    reader = csv.reader(
        io.StringIO(raw_csv, newline=""),
        delimiter=",",
        quotechar='"',
        doublequote=True,
        strict=False,
    )

    records = [row for row in reader if row]

    if not records:
        return {"columns": [], "rows": []}

    def header_score(row: list[str]) -> tuple[float, int]:
        width_penalty = abs(len(row) - expected_width)
        nonempty = [value for value in row if value.strip()]
        if not nonempty:
            return (-1000.0, -width_penalty)

        text_count = sum(bool(re.search(r"[A-Za-z]", value)) for value in nonempty)
        numeric_count = sum(bool(re.fullmatch(r"\s*[-+]?\d+(?:\.\d+)?\s*", value)) for value in nonempty)
        unique_ratio = len(set(value.strip().casefold() for value in nonempty)) / len(nonempty)
        fullness = len(nonempty) / max(len(row), expected_width)
        score = (
            4.0 * text_count / len(nonempty)
            + 2.0 * unique_ratio
            + fullness
            - 2.0 * numeric_count / len(nonempty)
            - 0.15 * width_penalty
        )
        return score, -width_penalty

    candidates = [
        index for index, row in enumerate(records)
        if len(row) >= expected_width
    ]
    if candidates:
        header_index = max(candidates, key=lambda index: (header_score(records[index]), -index))
    else:
        header_index = max(
            range(len(records)),
            key=lambda index: (len(records[index]), header_score(records[index]), -index),
        )

    columns = list(records[header_index])
    if columns:
        columns[0] = columns[0].lstrip("\ufeff")
    if len(columns) < expected_width:
        columns.extend(f"column_{index + 1}" for index in range(len(columns), expected_width))

    rows = []
    for record in records[header_index + 1:]:
        values = list(record)
        if len(values) > len(columns):
            columns.extend(
                f"column_{index + 1}" for index in range(len(columns), len(values))
            )
        values.extend([""] * (len(columns) - len(values)))
        rows.append(values)

    return {"columns": columns, "rows": rows}
